.cu-accordion {
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  overflow: hidden;
}

.cu-accordion__item + .cu-accordion__item {
  border-block-start: 1px solid var(--cu-color-border-default);
}

.cu-accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  inline-size: 100%;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 0;
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font: inherit;
  font-weight: 600;
  text-align: start;
  cursor: pointer;
}

.cu-accordion__trigger:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: -3px;
}

.cu-accordion__content {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border-block-start: 1px solid var(--cu-color-border-default);
  color: var(--cu-color-fg-default);
}
